from datetime import datetime


def handle(context):
    user = context["user"]
    config = context.get("config", {})
    siape = str(user.get("siape") or "").strip()

    if not siape:
        return {
            "warnings": ["Usuario sem SIAPE; importacao automatica nao executada."]
        }

    periodo_meses = int(config.get("periodo_meses", 24))
    connection = str(config.get("connection", "db2_guri"))
    requisito_i_item_1_quantidade = 4

    return {
        "form_data_patch": {
            "automacoes": {
                "importar-dados-calculadora-progressao-docente": {
                    "connection": connection,
                    "siape": siape,
                    "periodo_meses": periodo_meses,
                    "executed_at": datetime.utcnow().isoformat(),
                    "source": "database_function"
                }
            },
            "pontuacao": {
                "quantities": {
                    "I-0": requisito_i_item_1_quantidade
                },
                "importados": {
                    "requisito_i_item_1": {
                        "siape": siape,
                        "periodo_meses": periodo_meses,
                        "quantidade": requisito_i_item_1_quantidade,
                        "origem": connection,
                        "status": "simulado_db2"
                    },
                    "encargos_didaticos": {
                        "siape": siape,
                        "periodo_meses": periodo_meses,
                        "quantidade_horas_aula_semanais_media": requisito_i_item_1_quantidade,
                        "origem": connection,
                        "status": "simulado_db2"
                    }
                }
            }
        },
        "messages": ["Requisito I - Item 1 preenchido automaticamente com quantidade 4."]
    }
